canvas.height = height;

let ctx = canvas.getContext("2d");

// Window background
ctx.fillStyle = "white";
ctx.fillRect(0, 0, width, height);

// Blue border
ctx.strokeStyle = "blue";
ctx.lineWidth = 4;
ctx.strokeRect(2, 2, width - 4, height - 4);

// Title bar
let titleHeight = 25;
ctx.fillStyle = "blue";
ctx.fillRect(0, 0, width, titleHeight);

// Title text
ctx.fillStyle = "white";
ctx.font = "14px Times New Roman";
ctx.fillText(title, 8, 17);

// Close button
let buttonSize = 18;
let buttonX = width - buttonSize - 4;
let buttonY = 4;

ctx.fillStyle = "darkred";
ctx.fillRect(buttonX, buttonY, buttonSize, buttonSize);

// X symbol
ctx.strokeStyle = "red";
ctx.lineWidth = 2;

ctx.beginPath();
ctx.moveTo(buttonX + 4, buttonY + 4);
ctx.lineTo(buttonX + buttonSize - 4, buttonY + buttonSize - 4);
ctx.moveTo(buttonX + buttonSize - 4, buttonY + 4);
ctx.lineTo(buttonX + 4, buttonY + buttonSize - 4);
ctx.stroke();

